// Some portions generated by Co-Pilot
import { render, screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { axe } from "vitest-axe";
import WGProjects from "../index";

describe("Working group projects", () => {
  it("makes each complete project card a single, named link", () => {
    render(<WGProjects />);
    const destinations = [
      { name: "Eclipse Temurin®", href: "/temurin" },
      { name: "Eclipse AQAvit", href: "/aqavit" },
      { name: "Eclipse Mission Control", href: "/jmc" },
    ];

    expect(screen.getAllByRole("link")).toHaveLength(3);
    for (const { name, href } of destinations) {
      const card = screen.getByRole("link", { name });
      expect(card).toHaveAttribute("href", href);
      expect(
        within(card).getByRole("heading", { level: 3, name }),
      ).toBeVisible();
      expect(within(card).queryByRole("button")).not.toBeInTheDocument();
    }
  });

  it("has an accessible section heading and no accessibility violations", async () => {
    const { container } = render(<WGProjects />);
    expect(screen.getByRole("region", { name: "Text" })).toBeInTheDocument();
    expect(await axe(container)).toHaveNoViolations();
  });
});
